 baseline=json.loads((HERE/'archive/104-final/baseline.json').read_text(encoding='utf-8'));initial={'commit':baseline['commit'],'productionSourceSha256':hashlib.sha256(json.dumps(baseline['production'],sort_keys=True,separators=(',',':')).encode()).hexdigest(),'ngramSha256':baseline['production']['assets/knowledge/ngram.bin'],'datasetSha256':baseline['datasets'],'stageBReport':'stage_b-audited_pipeline_dev.json','note':'Derived summary of immutable initial per-file hashes; original reports not overwritten.'}
